<script setup lang="ts">
import { useOpenState } from '../primitives/state'
export type BlockAction={id:string,label:string,icon?:string,disabled?:boolean,active?:boolean,badge?:string,shortcut?:string,ariaLabel?:string,onClick?:()=>void}
const props=withDefaults(defineProps<{items:BlockAction[],expanded?:boolean,defaultExpanded?:boolean,activeId?:string,expandOnHover?:boolean,size?:string}>(),{expanded:undefined,defaultExpanded:false,expandOnHover:true})
const emit=defineEmits<{'update:expanded':[value:boolean],expandedChange:[value:boolean],action:[item:BlockAction]}>()
const {open,setOpen}=useOpenState(()=>props.expanded,props.defaultExpanded,next=>{emit('update:expanded',next);emit('expandedChange',next)})
function select(item:BlockAction,event:MouseEvent){if(item.disabled)return;if(props.expandOnHover&&!open.value&&event.detail>0&&matchMedia('(hover:none)').matches){setOpen(true);return}item.onClick?.();emit('action',item)}
</script>
<template><div class="be-block be-action-bar" role="toolbar" aria-label="Actions" :data-expanded="open" @pointerenter="expandOnHover && $event.pointerType==='mouse' && setOpen(true)" @pointerleave="expandOnHover && $event.pointerType==='mouse' && setOpen(false)" @keydown.esc="setOpen(false)"><button v-for="item in items" :key="item.id" type="button" class="be-block-button" :aria-label="item.ariaLabel??item.label" :aria-pressed="item.active??(activeId===item.id)" :disabled="item.disabled" @click="select(item,$event)"><slot name="icon" :item="item">{{ item.icon??item.label.slice(0,1) }}</slot><span v-if="open">{{ item.label }}</span><small v-if="item.badge">{{ item.badge }}</small></button><button type="button" class="be-block-button" :aria-expanded="open" :aria-label="open?'Collapse actions':'Expand actions'" @click="setOpen(!open)">{{ open?'‹':'›' }}</button></div></template>
<style scoped>.be-action-bar{display:inline-flex;align-items:center;gap:.2rem;padding:.25rem;width:fit-content;max-width:100%;overflow-x:auto;border:1px solid var(--beui-border);border-radius:.8rem}.be-action-bar button{border:0;white-space:nowrap}.be-action-bar button span{animation:be-lab-in .16s ease-out}@keyframes be-lab-in{from{opacity:0;transform:translateX(-3px)}}@media(prefers-reduced-motion:reduce){.be-action-bar button span{animation:none}}</style>
